parameters.functionCode:
const clients = $input.all().map(i => i.json);
const alerts = [];
const summary = {
  total_clients: clients.length,
  healthy: 0,
  warning: 0,
  critical: 0
};

for (const client of clients) {
  const contactUsage = client.contact_count / client.max_contacts;
  const keywordUsage = client.keyword_count / client.max_keywords;
  const emailUsage = client.emails_this_month / client.max_emails_per_month;

  let status = 'healthy';
  const clientAlerts = [];

  // Contact limit warnings
  if (contactUsage >= 0.95) {
    clientAlerts.push({ type: 'critical', message: `Contact limit at ${Math.round(contactUsage * 100)}% (${client.contact_count}/${client.max_contacts})` });
    status = 'critical';
  } else if (contactUsage >= 0.8) {
    clientAlerts.push({ type: 'warning', message: `Contact usage at ${Math.round(contactUsage * 100)}%` });
    if (status !== 'critical') status = 'warning';
  }

  // Keyword limit
  if (keywordUsage >= 0.9) {
    clientAlerts.push({ type: 'warning', message: `Keyword limit at ${Math.round(keywordUsage * 100)}%` });
    if (status !== 'critical') status = 'warning';
  }

  // Email limit
  if (emailUsage >= 0.9) {
    clientAlerts.push({ type: 'critical', message: `Email limit at ${Math.round(emailUsage * 100)}% this month` });
    status = 'critical';
  } else if (emailUsage >= 0.7) {
    clientAlerts.push({ type: 'warning', message: `Email usage at ${Math.round(emailUsage * 100)}% this month` });
    if (status !== 'critical') status = 'warning';
  }

  // Error rate
  if (client.errors_24h > 10) {
    clientAlerts.push({ type: 'critical', message: `${client.errors_24h} errors in last 24h` });
    status = 'critical';
  } else if (client.errors_24h > 3) {
    clientAlerts.push({ type: 'warning', message: `${client.errors_24h} errors in last 24h` });
    if (status !== 'critical') status = 'warning';
  }

  // Inactivity check
  if (client.last_activity) {
    const daysSinceActivity = (Date.now() - new Date(client.last_activity).getTime()) / (1000 * 60 * 60 * 24);
    if (daysSinceActivity > 7) {
      clientAlerts.push({ type: 'info', message: `No activity for ${Math.round(daysSinceActivity)} days` });
    }
  }

  summary[status]++;

  if (clientAlerts.length > 0) {
    alerts.push({
      client_id: client.client_id,
      client_code: client.client_code,
      company_name: client.company_name,
      contact_email: client.contact_email,
      status: status,
      alerts: clientAlerts,
      usage: {
        contacts: `${client.contact_count}/${client.max_contacts}`,
        keywords: `${client.keyword_count}/${client.max_keywords}`,
        emails: `${client.emails_this_month}/${client.max_emails_per_month}`
      }
    });
  }
}

return [{ json: { summary, alerts, has_critical: summary.critical > 0 } }];

parameters.text:
📊 *Daily Client Usage Report*

*Summary:*
• ✅ Healthy: {{ $json.summary.healthy }}
• ⚠️ Warning: {{ $json.summary.warning }}
• 🚨 Critical: {{ $json.summary.critical }}

{{ $json.has_critical ? '🚨 *CRITICAL ALERTS:*' : '⚠️ *Alerts:*' }}
{{ $json.alerts.map(a => `\n*${a.company_name}* (${a.client_code}) - ${a.status.toUpperCase()}\n${a.alerts.map(al => `  • [${al.type}] ${al.message}`).join('\n')}\n  Usage: Contacts ${a.usage.contacts} | Keywords ${a.usage.keywords} | Emails ${a.usage.emails}`).join('\n') }}

