// Send email to critical clients about their usage
const data = $input.first().json;
const criticalAlerts = data.alerts.filter(a => a.status === 'critical');

return criticalAlerts.map(alert => ({
  json: {
    to_email: alert.contact_email,
    client_code: alert.client_code,
    company_name: alert.company_name,
    alerts: alert.alerts,
    usage: alert.usage
  }
}));
